": "90ac828f-a4bc-4198-8907-ae8af4c6efb2", "type": "concept", "title": "syntax"}, {"id": "b8fa37e3-279d-4546-8383-d50fa2703da8", "type": "concept", "title": "meter"}, {"id": "8d1f33e6-f1f1-410e-83f9-db33e27d85a4", "type": "concept", "title": "imagery"}, {"id": "d7473718-6e86-4c04-98ca-dd915108967d", "type": "concept", "title": "motif"}, {"id": "d7379a90-c5b4-4fb8-9272-ccdcd0778541", "type": "concept", "title": "quotation integration"}], "description": "Students learn to build arguments from language, form, pattern, and textual detail."}, {"id": "c939b8e6-6295-4d80-892c-83b5e03b5641", "type": "subtopic", "title": "Historical Research", "children": [{"id": "271badb4-c2d2-4289-8f49-b3f43805c6cc", "type": "concept", "title": "scholarly edition"}, {"id": "a3d99de2-1691-4aa1-8b13-24cffd639858", "type": "concept", "title": "historical archive"}, {"id": "dd9d2621-2283-4068-afc1-787afaea10ff", "type": "concept", "title": "periodical database"}, {"id": "ae9d8fb2-15ca-426c-a86c-ecb6fb2e25d6", "type": "concept", "title": "annotated bibliography"}, {"id": "b4278f5e-55f0-4f51-8fcd-db4aa8b43d9b", "type": "concept", "title": "primary source"}], "description": "This subtopic turns context into evidence rather than background summary."}, {"id": "f839a524-8895-42a1-8bd8-be0a51a442f3", "type": "subtopic", "title": "Argument and Citation", "children": [{"id": "011600f6-8c9e-4ff7-83fd-605257760623", "type": "concept", "title": "thesis"}, {"id": "8a3a5b2a-e654-4f82-868f-caf53ecca59a", "type": "concept", "title": "topic sentence"}, {"id": "5ef20534-a93a-4fd3-913e-f895a82ed469", "type": "concept", "title": "counterargument"}, {"id": "e54d2667-77b5-402b-8050-3ae1ccd53f0b", "type": "concept", "title": "MLA citation"}, {"id": "92abb52b-a97d-4f31-951e-37f13e638afe", "type": "concept", "title": "works cited"}, {"id": "b977a9d9-48ae-4249-b250-ad759fe1788e", "type": "concept", "title": "interpretive stakes"}], "description": "Students learn how to shape a literary essay with a contestable claim and responsible sources."}]}], "dbBacked": true}$britjson$::jsonb,
