update public.learning_paths
set
  title = '18th-19th Century British Literature',
  goal = '18th-19th Century British Literature',
  summary = 'Coffeehouse culture, print, satire, and the political public sphere open the period, followed by Augustan satire, the rise of the novel, sensibility and Gothic prose, and Romantic poetry of imagination, nature, and revolution. Later units take up abolition, empire, and reform; Victorian industrial society, women writers, and poetry; aestheticism and fin-de-siecle culture; imperial adventure and colonial critique; and research, close reading, and literary argument.',
